effect.shader:
const float LARGURA_MAX = 720.0;     // a maior largura do desfoque, em px do buffer

// Os sliders do Sapphire chegam em ponto fixo 16.16 (medido: o limiar 0,3 é 0,3000031 no AE).
float fixo(float v) { return floor(v * 65536.0 + 0.5) / 65536.0; }

// ---- a camada do AE no buffer --------------------------------------------------------------
ivec2 gT;          // o buffer
ivec2 gN;          // a camada do AE dentro dele, em px
ivec2 gInicio;     // o canto da camada no buffer
float gEscala;     // a prévia reduzida (o Blur Input é em px da composição)

void preparar() {
    gT = textureSize(inputImg, 0);
    gN = clamp(ivec2(floor(max(acCamada, vec2(0.001)) * vec2(gT) + 0.5)), ivec2(1), gT);
    gInicio = (gT - gN) / 2;
    gEscala = acEscalaDePixel > 0.0 ? acEscalaDePixel : 1.0;
}

/** Espelha o índice na camada repetindo o pixel da borda (abc|cba), quantas voltas forem. */
int espelhar(int i, int n) {
    // Dentro do quadro o espelho é o próprio índice: sem a divisão inteira, que em todo tap custava caro (0.569.0)
    if (i >= 0 && i < n) return i;
    int p = 2 * n;
    i = i - (i / p) * p; if (i < 0) i += p;
    return i < n ? i : p - 1 - i;
}

ivec2 naCamada(ivec2 q) {
    return gInicio + ivec2(espelhar(q.x, gN.x), espelhar(q.y, gN.y));
}

// ---- o núcleo das três caixas --------------------------------------------------------------
// Largura inteira n -> raios r0 ≥ r1 ≥ r2 que somam n ((n + 2 − i) div 3). A soma das caixas r1 e r2 é um
// trapézio T (contagens); a das três, em d, é Σ T(d − i) com |i| ≤ r0 = S(d + r0) − S(d − r0 − 1), S a soma
// acumulada de T. Tudo em inteiros (exato), dividido no fim por (2r0 + 1)(2r1 + 1)(2r2 + 1).

// Σ T(j) para 0 ≤ j ≤ x (x ≥ 0), com p = r2 ≤ q = r1.
int somaDoTrapezio(int x, int p, int q) {
    int m = q - p;
    int M = p + q;
    x = min(x, M);
    if (x <= m) return (x + 1) * (2 * p + 1);
    return (m + 1) * (2 * p + 1) + (x - m) * (M + 1) - (x * (x + 1) - m * (m + 1)) / 2;
}

// Σ T(j) para j ≤ x.
int acumulado(int x, int p, int q) {
    int total = (2 * p + 1) * (2 * q + 1);
    int meio = (total - (2 * p + 1)) / 2;      // os j < 0 (T(0) = 2p + 1)
    if (x >= 0) return meio + somaDoTrapezio(x, p, q);
    return total - (meio + somaDoTrapezio(-x - 1, p, q));       // T é simétrico
}

float pesoDasCaixas(int d, int n) {
    if (n <= 0) return d == 0 ? 1.0 : 0.0;
    int r0 = (n + 2) / 3;
    int r1 = (n + 1) / 3;
    int r2 = n / 3;
    if (abs(d) > n) return 0.0;
    int c = acumulado(d + r0, r2, r1) - acumulado(d - r0 - 1, r2, r1);
    return float(c) / (float(2 * r0 + 1) * float(2 * r1 + 1) * float(2 * r2 + 1));
}

// ---- 21 bits por canal em dois buffers (do Add Grain) ---------------------------------------
uvec2 palavras(vec3 u) {
    uvec3 q = uvec3(floor(clamp(u, 0.0, 1.0) * 2097151.0 + 0.5));
    return uvec2(q.x | (q.y << 21), (q.y >> 11) | (q.z << 10));
}

vec4 bytes(uint w) {
    return vec4(float(w & 255u), float((w >> 8) & 255u), float((w >> 16) & 255u), float(w >> 24)) / 255.0;
}

uint palavra(vec4 c) {
    uvec4 b = uvec4(floor(c * 255.0 + 0.5));
    return b.x | (b.y << 8) | (b.z << 16) | (b.w << 24);
}

vec3 valores(vec4 c0, vec4 c1) {
    uint a = palavra(c0);
    uint b = palavra(c1);
    return vec3(uvec3(a & 2097151u, (a >> 21) | ((b & 1023u) << 11), b >> 10)) / 2097151.0;
}

// ---- a fonte e a máscara --------------------------------------------------------------------
// Opacity (medido): Normal (1) trabalha na cor pré-multiplicada; All Opaque (0) e As Premult (2), na cor reta.
vec3 entrada(ivec2 p) {
    vec4 s = texelFetch(inputImg, p, 0);
    return opacity == 1 ? s.rgb * s.a : s.rgb;
}

bool temMascara() { return textureSize(maskImg, 0).x > 1; }

// A camada de máscara no lugar dela na composição: (5R + 8G + 3B)/16 da cor pré-multiplicada, ou o alfa.
float mascara(ivec2 p) {
    vec4 m = texture(maskImg, (vec2(p) + 0.5) / vec2(gT));
    float v = maskUse == 1 ? m.a : dot(m.rgb * m.a, vec3(0.3125, 0.5, 0.1875));
    return invertMask ? 1.0 - v : v;
}

vec4 gravarMascara(float m) {
    float a = floor(clamp(m, 0.0, 1.0) * 16777215.0 + 0.5);
    float b0 = floor(a / 65536.0);
    float r = a - b0 * 65536.0;
    float b1 = floor(r / 256.0);
    return vec4(b0, b1, r - b1 * 256.0, 255.0) / 255.0;
}

float lerMascara(vec4 v) {
    vec3 b = floor(v.rgb * 255.0 + 0.5);
    return (b.x * 65536.0 + b.y * 256.0 + b.z) / 16777215.0;
}

// A largura do desfoque em px do buffer.
float larguraDaEntrada() { return clamp(fixo(blurInput) * gEscala, 0.0, LARGURA_MAX); }
// A da máscara, arredondada (o subpixel 0 da definição: meio para cima).
int larguraDaMascara() { return int(clamp(floor(fixo(blurMask) * gEscala + 0.5), 0.0, LARGURA_MAX)); }

// O desfoque da fonte num eixo: (1 − f)·núcleo(⌊W⌋) + f·núcleo(⌊W⌋ + 1).
vec3 desfoqueEmX(ivec2 q) {
    float w = larguraDaEntrada();
    int a = int(floor(w));
    float f = w - float(a);
    vec3 soma = vec3(0.0);
    for (int d = -a - 1; d <= a + 1; d++) {
        float k = (1.0 - f) * pesoDasCaixas(d, a) + f * pesoDasCaixas(d, a + 1);
        if (k == 0.0) continue;
        soma += k * entrada(naCamada(q + ivec2(d, 0)));
    }
    return soma;
}

vec3 desfoqueEmY(ivec2 q) {
    float w = larguraDaEntrada();
    int a = int(floor(w));
    float f = w - float(a);
    vec3 soma = vec3(0.0);
    for (int d = -a - 1; d <= a + 1; d++) {
        float k = (1.0 - f) * pesoDasCaixas(d, a) + f * pesoDasCaixas(d, a + 1);
        if (k == 0.0) continue;
        ivec2 p = naCamada(q + ivec2(0, d));
        soma += k * valores(texelFetch(hA, p, 0), texelFetch(hB, p, 0));
    }
    return soma;
}

float mascaraDesfocada(ivec2 q, bool emX) {
    int n = larguraDaMascara();
    float soma = 0.0;
    for (int d = -n; d <= n; d++) {
        float k = pesoDasCaixas(d, n);
        if (k == 0.0) continue;
        ivec2 p = naCamada(q + (emX ? ivec2(d, 0) : ivec2(0, d)));
        soma += k * (emX ? mascara(p) : lerMascara(texelFetch(mH, p, 0)));
    }
    return soma;
}

void main() {
    preparar();
    ivec2 t = min(ivec2(floor(acScreenNorm * vec2(gT))), gT - ivec2(1));
    ivec2 q = t - gInicio;
    bool fora = any(lessThan(q, ivec2(0))) || any(greaterThanEqual(q, gN));

    if (acPass == 0) {
        fragColor = fora ? vec4(0.0) : bytes(palavras(desfoqueEmX(q)).x);
        return;
    }
    if (acPass == 1) {
        fragColor = fora ? vec4(0.0) : bytes(palavras(desfoqueEmX(q)).y);
        return;
    }
    if (acPass == 2) {
        fragColor = (fora || !temMascara()) ? vec4(0.0) : gravarMascara(mascaraDesfocada(q, true));
        return;
    }

    // ---- 3: o resto ----
    vec4 s = texelFetch(inputImg, t, 0);
    if (fora) {
        fragColor = s;
        return;
    }
    vec3 x = larguraDaEntrada() > 0.0 ? desfoqueEmY(q) : entrada(t);

    // hotspots (0x180fa6320): a cor vezes Σ max(c − th, 0) / Σ max(c, 0)
    vec3 th = fixo(threshold) + floor(thresholdAddColor.rgb * 255.0 + 0.5) / 255.0;
    float b = fixo(brightness) / max(0.01, 1.0 - min(th.r, min(th.g, th.b)));
    vec3 passa = max(x - th, vec3(0.0));
    vec3 pos = max(x, vec3(0.0));
    float e = passa.r + passa.g + passa.b;
    float sm = pos.r + pos.g + pos.b;
    vec3 h = (e > 0.0 && sm > 0.0) ? x * (e / sm) : vec3(0.0);

    // sat_scale (0x180f16c20)
    vec3 c = b * h;
    float sat = fixo(saturation);
    float luma = (0.1875 * c.b + 0.5 * c.g) + 0.3125 * c.r;      // na ordem do plugin
    vec3 r = clamp(c * sat + luma * (1.0 - sat), 0.0, 1.0);

    float a = s.a;
    if (opacity == 0) a = 1.0;                 // All Opaque: sai opaco
    else if (opacity == 2) r *= a;             // As Premult: o resultado volta reto (em pré-multiplicado, r · alfa)

    if (temMascara()) {
        float m = larguraDaMascara() > 0 ? mascaraDesfocada(q, false) : mascara(t);
        vec3 sp = s.rgb * s.a;
        r = sp + (r - sp) * m;
        a = s.a;
    }

    vec3 reta = a > 0.0 ? min(r / a, vec3(1.0)) : vec3(0.0);
    // a saída em níveis inteiros, arredondada como o AE de 8 bpc (a da GPU não arredonda igual)
    fragColor = vec4(floor(reta * 255.0 + 0.5) / 255.0, a);
}
